const days = 14;
const hotelNights = 13;
const hotelPerNight = 15_000;
const railPass = 50_000;
const dailyFoodUsd = 15;
const yenPerUsd = 150;

const foodYen = dailyFoodUsd * yenPerUsd * days;
const totalYen = hotelNights * hotelPerNight + railPass + foodYen;
const dailyYen = totalYen / days;

console.log(`Total: ¥${totalYen.toLocaleString()} ($${(totalYen / yenPerUsd).toFixed(2)})`);
console.log(`Daily average: ¥${dailyYen.toLocaleString("en-US", { maximumFractionDigits: 2 })} ($${(dailyYen / yenPerUsd).toFixed(2)})`);

